{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C21"],
      "claim": "Tolbutamide, the closest sulfonylurea analogue, has an absolute oral bioavailability of 0.85 in humans after a 500 mg oral dose versus IV, directly supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Glimepiride, another sulfonylurea with the same p-toluenesulfonyl urea motif, showed 97% absolute bioavailability (90% CI 93-102%) in healthy volunteers, supporting essentially complete oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Levosulpiride, a less similar sulfonamide, had an absolute oral bioavailability of 23.4% in humans, still above the 20% threshold, showing that even poorly absorbed sulfonamide-type drugs meet the high criterion.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Sulfamethoxazole, a sulfonamide, has human oral bioavailability greater than 80%, providing additional supportive evidence for the absorbability of sulfonamide/sulfonylurea-class compounds.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a p-toluenesulfonyl semicarbazide with a fused bicyclic amine, closely related to sulfonylurea drugs. The closest analogue tolbutamide has absolute oral bioavailability of 85%, and glimepiride is approximately 97-100% bioavailable. Even less absorbed sulfonamide analogues such as levosulpiride (23.4%) exceed the 20% threshold. Therefore the query is predicted to have high oral bioavailability (F >= 20%).",
  "evidence_gaps": [
    "No direct human or animal bioavailability measurement is available for the query molecule.",
    "The query's hydrazide/semicarbazide linker is not exactly represented in the retrieved analogues, so its metabolic stability and permeability are inferred rather than directly measured.",
    "A tolperisone record reports 'very low' oral bioavailability without a numeric value; if its true F is below 20% it would be a weak contradictory signal, but it is structurally distant and not threshold-specific."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

